<?php
require_once __DIR__.'/config/module_helpers.php';simrs_require_login();$role=$_SESSION['role_code']??'';$reportRoles=['simrs_admin','it_manager','registration_staff','unit_manager','management','auditor'];if(!in_array($role,$reportRoles,true)){http_response_code(403);exit('Akses ditolak. Role akun Anda tidak memiliki izin melihat laporan.');}
try{$patients=(int)$pdo->query('SELECT COUNT(*) FROM patients')->fetchColumn();$encounters=(int)$pdo->query('SELECT COUNT(*) FROM encounters')->fetchColumn();$edToday=(int)$pdo->query("SELECT COUNT(*) FROM encounters WHERE encounter_type='ED' AND DATE(arrival_at)=CURDATE()")->fetchColumn();$rad=(int)$pdo->query("SELECT COUNT(*) FROM radiology_orders WHERE status<>'cancelled'")->fetchColumn();$radFinal=(int)$pdo->query("SELECT COUNT(*) FROM radiology_orders WHERE status='final'")->fetchColumn();$appointments=(int)$pdo->query('SELECT COUNT(*) FROM appointments')->fetchColumn();$apptToday=(int)$pdo->query('SELECT COUNT(*) FROM appointments WHERE appointment_date=CURDATE()')->fetchColumn();$recent=$pdo->query("SELECT a.appointment_no,a.appointment_date,a.start_time,a.status,p.full_name,u.unit_name FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN units u ON u.id=a.unit_id ORDER BY a.appointment_date DESC,a.start_time DESC LIMIT 10")->fetchAll();}catch(Throwable $e){$err=simrs_db_error($e);$patients=$encounters=$edToday=$rad=$radFinal=$appointments=$apptToday=0;$recent=[];}
simrs_layout_start('Reports','Reports');if(isset($err))echo '<div class="errorbox">'.simrs_h($err).'</div>';
?>
<h1>Reports</h1><div class="subtitle">Ringkasan aktivitas aktual dari database SIMRS lokal.</div><div class="cards"><div class="card"><div class="label">Registered Patients</div><div class="num"><?=$patients?></div></div><div class="card"><div class="label">ED Encounters</div><div class="num"><?=$encounters?></div><div class="hint"><?=$edToday?> hari ini</div></div><div class="card"><div class="label">Radiology Orders</div><div class="num"><?=$rad?></div><div class="hint"><?=$radFinal?> final report</div></div></div><div class="cards"><div class="card"><div class="label">Appointments</div><div class="num"><?=$appointments?></div><div class="hint"><?=$apptToday?> hari ini</div></div></div><div class="panel"><div class="panel-title">10 Appointment Terbaru</div><div class="tablewrap"><table><thead><tr><th>No. Appointment</th><th>Pasien</th><th>Unit</th><th>Tanggal</th><th>Jam</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=simrs_h($r['appointment_no'])?></td><td><?=simrs_h($r['full_name'])?></td><td><?=simrs_h($r['unit_name'])?></td><td><?=simrs_h($r['appointment_date'])?></td><td><?=simrs_h(substr($r['start_time'],0,5))?></td><td><?=simrs_h($r['status'])?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="6">Belum ada appointment.</td></tr><?php endif;?></tbody></table></div></div><?php simrs_layout_end(); ?>
